  "test_path": "tests/unit/test_observe_error_recording.py",
  "test": "import pytest
from langfuse import observe
from langfuse._client.attributes import LangfuseOtelSpanAttributes


def _finished_spans_by_name(memory_exporter, name):
    return [s for s in memory_exporter.get_finished_spans() if s.name == name]


def test_observe_without_error_recording(langfuse_memory_client, memory_exporter):
    @observe(name="no_error_record", record_error=False)
    def will_fail():
        raise ValueError("boom")

    with pytest.raises(ValueError):
        will_fail()

    # flush collected spans
    langfuse_memory_client.flush()

    spans = _finished_spans_by_name(memory_exporter, "no_error_record")
    assert len(spans) == 1
    span = spans[0]
    # The span should not have an error level attribute when record_error=False
    assert LangfuseOtelSpanAttributes.OBSERVATION_LEVEL not in span.attributes
